import { composeServices } from '@theguild/federation-composition';
import {
  buildSchema,
  type DocumentNode,
  Kind,
  parse as parseGraphql,
  type OperationDefinitionNode,
  validate,
} from 'graphql';
import { parse, stringify } from 'yaml';
import type { ResolvedSubgraph } from './render.ts';
import type { ExternalIssuer } from './providers/supergraph.ts';
import { sha256Hex } from './sha256.ts';

export const SUPERGRAPH_HEADER_TEXT =
  'generated by `ortzi app supergraph` from every subgraph resource; edit app.yaml or the base config instead';

export interface Composed {
  supergraph: string;
  schema: string;
  router: string;
  node?: string;
  documents?: string;
}

export const NODE_SUBGRAPH = 'node';
export const KANIDM_ISSUER_BASE = 'https://idm.anurag.sh/oauth2/openid';
export const NODE_SUBGRAPH_URL = 'http://node-plugin.invalid/graphql';
export const PERSISTED_DOCUMENTS = 'persisted-documents.json';
const RELAY_TYPES = ['Node', 'PageInfo'];

export function compose(
  subgraphs: ResolvedSubgraph[],
  sdls: Record<string, string>,
  base: string,
  manifests: Record<string, string> = {},
  externalIssuers: ExternalIssuer[] = [],
): Composed {
  const services = subgraphs.map((subgraph) => ({
    name: subgraph.name,
    url: subgraph.url,
    typeDefs: parseGraphql(sdls[subgraph.name] as string),
  }));

  const unprefixed = subgraphs.flatMap((subgraph, i) => {
    const sdl = services[i].typeDefs;
    const fields = unprefixedRootFields(sdl, subgraph.prefix, subgraph.allowedRootFields);
    const others = subgraphs.filter((other) => other !== subgraph).map((other) => other.prefix);
    const types = unprefixedTypes(sdl, subgraph.prefix, others);
    return [
      ...(fields.length
        ? [
            `  ${subgraph.name}: root fields must start with ${subgraph.prefix}: ${fields.join(', ')}`,
          ]
        : []),
      ...(types.length
        ? [
            `  ${subgraph.name}: types must start with ${pascal(subgraph.prefix)}, or another subgraph's prefix for an entity it references: ${types.join(', ')}`,
          ]
        : []),
    ];
  });
  if (unprefixed.length) {
    throw new Error(`supergraph composition failed:\n${unprefixed.join('\n')}`);
  }

  const nodeTypes = nodeImplementers(subgraphs, services);
  const nodeSdl = nodeTypes.length ? nodeSubgraph(nodeTypes) : undefined;
  const result = composeServices([
    ...services,
    ...(nodeSdl
      ? [{ name: NODE_SUBGRAPH, url: NODE_SUBGRAPH_URL, typeDefs: parseGraphql(nodeSdl) }]
      : []),
  ]);

  if (result.errors) {
    throw new Error(
      `supergraph composition failed:\n${result.errors.map((e) => `  ${e.message}`).join('\n')}`,
    );
  }

  const documents = Object.keys(manifests).length ? mergeDocuments(manifests) : undefined;
  if (documents !== undefined) {
    validateDocuments(result.publicSdl, manifests);
  }

  return {
    supergraph: `# ${SUPERGRAPH_HEADER_TEXT}\n${result.supergraphSdl.trimEnd()}\n`,
    schema: `# ${SUPERGRAPH_HEADER_TEXT}\n${result.publicSdl.trimEnd()}\n`,
    router: routerConfig(subgraphs, base, nodeTypes, documents !== undefined, externalIssuers),
    ...(nodeSdl ? { node: `# ${SUPERGRAPH_HEADER_TEXT}\n${nodeSdl}` } : {}),
    ...(documents !== undefined ? { documents } : {}),
  };
}

export function validateDocuments(publicSdl: string, manifests: Record<string, string>): void {
  const schema = buildSchema(publicSdl);

  const problems = Object.entries(manifests).flatMap(([subgraph, manifest]) =>
    Object.entries(JSON.parse(manifest) as Record<string, string>).flatMap(([id, text]) => {
      let document: DocumentNode;
      try {
        document = parseGraphql(text);
      } catch (error) {
        return [`  ${subgraph}: persisted document ${id}: ${(error as Error).message}`];
      }

      const operation = document.definitions.find(
        (definition): definition is OperationDefinitionNode =>
          definition.kind === Kind.OPERATION_DEFINITION,
      );
      const label = `${subgraph}: persisted document ${operation?.name?.value ?? 'anonymous'} (${id})`;

      const errors = validate(schema, document).map((error) => `  ${label}: ${error.message}`);
      if (sha256Hex(text) !== id) {
        errors.push(`  ${label}: id is not the sha256 of its text`);
      }

      return errors;
    }),
  );

  if (problems.length) {
    throw new Error(`persisted documents do not match the supergraph:\n${problems.join('\n')}`);
  }
}

export function mergeDocuments(manifests: Record<string, string>): string {
  const merged = new Map<string, [string, string]>();

  for (const [subgraph, manifest] of Object.entries(manifests)) {
    const documents: unknown = JSON.parse(manifest);
    if (typeof documents !== 'object' || documents === null || Array.isArray(documents)) {
      throw new Error(`${subgraph}: persisted documents must be a JSON object of id to document`);
    }

    for (const [id, document] of Object.entries(documents)) {
      if (typeof document !== 'string') {
        throw new Error(`${subgraph}: persisted document ${id} is not a string`);
      }

      const existing = merged.get(id);
      if (existing && existing[1] !== document) {
        throw new Error(`persisted document ${id} differs between ${existing[0]} and ${subgraph}`);
      }
      merged.set(id, [subgraph, document]);
    }
  }

  const sorted = [...merged.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([id, [, document]]) => [id, document]);
  return `${JSON.stringify(Object.fromEntries(sorted), null, 2)}\n`;
}

function keyFields(
  directives: readonly { name: { value: string }; arguments?: readonly any[] }[] = [],
) {
  return directives
    .filter((directive) => directive.name.value === 'key')
    .map(
      (directive) => directive.arguments?.find((arg) => arg.name.value === 'fields')?.value.value,
    );
}

export function nodeImplementers(
  subgraphs: ResolvedSubgraph[],
  services: { name: string; typeDefs: DocumentNode }[],
): string[] {
  const missing: string[] = [];
  const types = services.flatMap((service, i) =>
    service.typeDefs.definitions.flatMap((definition) => {
      if (
        (definition.kind !== Kind.OBJECT_TYPE_DEFINITION &&
          definition.kind !== Kind.OBJECT_TYPE_EXTENSION) ||
        !definition.interfaces?.some((iface) => iface.name.value === 'Node')
      ) {
        return [];
      }
      const name = definition.name.value;
      if (!keyFields(definition.directives).includes('id')) {
        missing.push(`${subgraphs[i].name}: ${name}`);
      }
      return [name];
    }),
  );

  if (missing.length) {
    throw new Error(
      `supergraph composition failed:\n${missing.map((m) => `  ${m} implements Node without @key(fields: "id")`).join('\n')}`,
    );
  }
  return [...new Set(types)].sort();
}

export function nodeSubgraph(types: string[]): string {
  return [
    'extend schema @link(url: "https://specs.apollo.dev/federation/v2.3", import: ["@key"])',
    '',
    'type Query {',
    '  node(id: ID!): Node',
    '}',
    '',
    'interface Node {',
    '  id: ID!',
    '}',
    ...types.flatMap((type) => [
      '',
      `type ${type} implements Node @key(fields: "id", resolvable: false) {`,
      '  id: ID!',
      '}',
    ]),
    '',
  ].join('\n');
}

const pascal = (prefix: string) => prefix[0]!.toUpperCase() + prefix.slice(1);

function rootTypes(sdl: DocumentNode): Set<string> {
  const roots = new Set<string>();
  for (const definition of sdl.definitions) {
    if (definition.kind === Kind.SCHEMA_DEFINITION || definition.kind === Kind.SCHEMA_EXTENSION) {
      for (const operation of definition.operationTypes ?? []) {
        roots.add(operation.type.name.value);
      }
    }
  }
  if (!roots.size) {
    for (const name of ['Query', 'Mutation', 'Subscription']) {
      roots.add(name);
    }
  }
  return roots;
}

export function unprefixedRootFields(
  sdl: DocumentNode,
  prefix: string,
  allowed: string[] = [],
): string[] {
  const roots = rootTypes(sdl);
  const prefixed = new RegExp(`^${prefix}[A-Z0-9]`);
  return sdl.definitions.flatMap((definition) =>
    (definition.kind === Kind.OBJECT_TYPE_DEFINITION ||
      definition.kind === Kind.OBJECT_TYPE_EXTENSION) &&
    roots.has(definition.name.value)
      ? (definition.fields ?? [])
          .map((field) => field.name.value)
          .filter(
            (name) => !name.startsWith('_') && !prefixed.test(name) && !allowed.includes(name),
          )
          .map((name) => `${definition.name.value}.${name}`)
      : [],
  );
}

export function unprefixedTypes(sdl: DocumentNode, prefix: string, others: string[]): string[] {
  const roots = rootTypes(sdl);
  const starts = (name: string, prefix: string) =>
    new RegExp(`^${pascal(prefix)}[A-Z0-9]`).test(name);
  const named = new Set<Kind>([
    Kind.OBJECT_TYPE_DEFINITION,
    Kind.INTERFACE_TYPE_DEFINITION,
    Kind.UNION_TYPE_DEFINITION,
    Kind.ENUM_TYPE_DEFINITION,
    Kind.INPUT_OBJECT_TYPE_DEFINITION,
  ]);

  const names = sdl.definitions.flatMap((definition) => {
    if (!named.has(definition.kind) || !('name' in definition) || !definition.name) {
      return [];
    }
    const name = definition.name.value;
    const entity = (
      definition as { directives?: readonly { name: { value: string } }[] }
    ).directives?.some((directive) => directive.name.value === 'key');
    const federation = name.startsWith('_') || /^(link|federation)__/.test(name);
    const referenced = entity && others.some((other) => starts(name, other));
    const relay = RELAY_TYPES.includes(name);
    return roots.has(name) || federation || relay || referenced || starts(name, prefix)
      ? []
      : [name];
  });

  return [...new Set(names)].sort();
}

export function routerConfig(
  subgraphs: ResolvedSubgraph[],
  base: string,
  nodeTypes: string[],
  persistedDocuments = false,
  externalIssuers: ExternalIssuer[] = [],
): string {
  const config = (parse(base) ?? {}) as Record<string, any>;

  if (persistedDocuments) {
    const storage = config.supergraph?.storage_id;
    if (config.supergraph?.source !== 'storage' || !storage) {
      throw new Error(
        'persisted documents are stored beside the supergraph, which must load from storage',
      );
    }

    config.persisted_documents = {
      enabled: true,
      require_id: true,
      storage: {
        type: 'storage',
        storage_id: storage,
        location: PERSISTED_DOCUMENTS,
        poll_interval: config.supergraph.poll_interval,
      },
    };
  }

  if (nodeTypes.length) {
    config.plugins = {
      ...config.plugins,
      node: { enabled: true, config: { subgraph: NODE_SUBGRAPH, types: nodeTypes } },
    };
  }
  const gated = subgraphs.filter((subgraph) => subgraph.auth);

  if (gated.length) {
    const clients = [...new Set(gated.flatMap((subgraph) => subgraph.auth!.clients))].sort();
    const issuers = clients.map((client) => `${KANIDM_ISSUER_BASE}/${client}`);
    const external = externalIssuers.filter((issuer) =>
      gated.some((subgraph) =>
        subgraph.auth!.external?.some((pattern) => pattern.issuer === issuer.name),
      ),
    );

    config.jwt = {
      enabled: true,
      require_authentication: false,
      jwks_providers: [
        ...issuers.map((issuer) => ({
          source: 'remote',
          url: `${issuer}/public_key.jwk`,
          refresh_on_unknown_kid: '30s',
        })),
        ...external.map((issuer) => ({
          source: 'remote',
          url: issuer.jwks,
          refresh_on_unknown_kid: '30s',
        })),
      ],
      issuers: [...issuers, ...external.map((issuer) => issuer.issuer)],
      ...(external.length
        ? { audiences: [...clients, ...external.map((issuer) => issuer.audience)] }
        : {}),
    };
    config.plugins = {
      ...config.plugins,
      access: {
        enabled: true,
        config: {
          ...(external.length
            ? {
                external_issuers: Object.fromEntries(
                  external.map((issuer) => [issuer.name, issuer.issuer]),
                ),
              }
            : {}),
          subgraphs: Object.fromEntries(
            gated.map((subgraph) => [
              subgraph.name,
              {
                issuers: subgraph.auth!.clients.map((client) => `${KANIDM_ISSUER_BASE}/${client}`),
                groups: subgraph.auth!.groups,
                ...(subgraph.auth!.external?.length ? { external: subgraph.auth!.external } : {}),
              },
            ]),
          ),
        },
      },
    };
  }

  const websockets = subgraphs.filter((subgraph) => subgraph.websocket);

  if (websockets.length) {
    config.subscriptions = {
      enabled: true,
      ...config.subscriptions,
      websocket: {
        ...config.subscriptions?.websocket,
        subgraphs: {
          ...config.subscriptions?.websocket?.subgraphs,
          ...Object.fromEntries(
            websockets.map((subgraph) => [subgraph.name, { path: subgraph.websocket }]),
          ),
        },
      },
    };
  }

  return `# ${SUPERGRAPH_HEADER_TEXT}\n${stringify(config, { lineWidth: 0 })}`;
}
